  let best=safeBest(),progress=safeProgress(),badges=safeStore(badgeKey),dailyDone=safeStore(dailyKey),mode='noodle',state=null,lastFrame=0,keys=new Set(),pointerStart=null,runToken=0,selectedPower={};
  function safeBest(){try{return JSON.parse(localStorage.getItem(bestKey)||'{}')||{}}catch{return {}}}
  function safeProgress(){try{return JSON.parse(localStorage.getItem(progressKey)||'{}')||{}}catch{return {}}}
