  function updatePowerUI(){const select=$('power-select'),button=$('power-button'),quickbar=$('power-quickbar'),defs=powerDefs[mode],level=state?.level||1,current=selectedPower[mode];select.replaceChildren();quickbar.replaceChildren();for(const power of defs){const option=document.createElement('option');option.value=power.id;const locked=power.unlock>level,charges=state?.powerCharges?.[power.id]||0;option.textContent=locked?`${power.label} · unlock Level ${power.unlock}`:state?`${power.label} · ${charges} charge${charges===1?'':'s'}`:`${power.label} · ready at Level ${power.unlock}`;option.disabled=locked;select.append(option);const quick=document.createElement('button');quick.type='button';quick.className='power-quick';quick.disabled=locked||!state?.live||charges<1;quick.setAttribute('aria-label',`${locked?'Locked until level '+power.unlock:power.label.replace(/^\S+\s/, '')+' · '+charges+' charges · tap to use'}`);quick.title=locked?`Unlock at level ${power.unlock}`:`Tap to use ${power.label.replace(/^\S+\s/, '')}`;quick.innerHTML=`<span class="power-quick-icon" aria-hidden="true">${power.label.match(/^\S+/)?.[0]||'✦'}</span><span>${power.label.replace(/^\S+\s/, '')}</span><b>${locked?'🔒':charges}</b>`;quick.classList.toggle('is-selected',power.id===current);quickbar.append(quick);quick.addEventListener('click',()=>{if(quick.disabled)return;selectedPower[mode]=power.id;select.value=power.id;powerUseFromButton()})}const firstAvailable=defs.find(power=>power.unlock<=level);if(!firstAvailable)return;const chosen=defs.find(power=>power.id===current&&power.unlock<=level)||firstAvailable;selectedPower[mode]=chosen.id;select.value=chosen.id;const charges=state?.powerCharges?.[chosen.id]||0;button.textContent=state?.awaitingNext?`Ready for Level ${state.level}`:state?`Use ${chosen.label} · ${charges} left`:`Choose a power-up during play`;button.disabled=!state?.live||charges<1}
