  function hurt(message){if(!state?.live)return;state.streak=0;state.shake=.22;const x=mode==='match'?480:mode==='roadster'?272+state.lane*208:mode==='trailblazer'?264+(state.cell%5)*88+40:mode==='lantern'?40+(state.snake[0].x+.5)*40:mode==='teatoss'?state.ball.x:mode==='wok'?state.birdX:mode==='ace'?480+Math.cos(state.angle)*170:state.playerX||480,y=mode==='match'?275:mode==='roadster'?462:mode==='trailblazer'?54+Math.floor(state.cell/5)*88+40:mode==='lantern'?40+(state.snake[0].y+.5)*40:mode==='teatoss'?state.ball.y:mode==='wok'?state.birdY:mode==='ace'?282+Math.sin(state.angle)*170:450;burst(x,y,'#ef7469',14);if(state.practice){statusEl.textContent=`Practice: ${message} No heart lost.`;syncHud();return}state.lives--;statusEl.textContent=message;if(state.lives<=0)end(false,message);syncHud()}
  function addScore(n=1){state.score+=n;syncHud()}function awardSkillScore(base){state.streak=(state.streak||0)+1;const bonus=Math.min(state.streak-1,8)*25;addScore(base+bonus);return bonus}
